export const folderFormLogic: LogicWrapper<folderFormLogicType> = kea<folderFormLogicType>([
    props({} as FolderFormLogicProps),
    key((props) => props.dialog),
    path((key) => ['lib', 'components', 'FileSystem', 'FolderSelect', 'folderFormLogic', key]),
    connect(() => ({
        values: [projectTreeDataLogic, ['lastNewFolder']],
        actions: [projectTreeDataLogic, ['setLastNewFolder']],
    })),
    actions({
        startFrom: (items: FileSystemEntry[]) => ({ items }),
    }),
    forms({
        form: {
            defaults: {
                folder: null as string | null,
            },
            errors: ({ folder }) => ({
                folder: typeof folder !== 'string' ? 'You need to specify a folder.' : null,
            }),
        },
    }),
    listeners(({ actions, values }) => ({
        setLastNewFolder: ({ folder }) => {
            actions.setFormValue('folder', folder)
        },
        startFrom: ({ items }) => {
            actions.setFormValue(
                'folder',
                typeof values.lastNewFolder === 'string' ? values.lastNewFolder : parentPath(items[0].path)
            )
        },
    })),
])
